public static void check(Solution solution) {
    assert Arrays.equals(solution.shiftingLetters("world", new int[]{{0,4,0},{0,4,0},{0,4,0},{0,4,0}}), sknhz);
    assert Arrays.equals(solution.shiftingLetters("abc", new int[]{{0,1,0},{1,2,1},{0,2,1}}), ace);
    assert Arrays.equals(solution.shiftingLetters("xyz", new int[]{{0,2,0}}), wxy);
    assert Arrays.equals(solution.shiftingLetters("abcdef", new int[]{{1,4,1},{2,3,0}}), accdff);
    assert Arrays.equals(solution.shiftingLetters("aaa", new int[]{{0,2,1},{0,2,1},{0,2,1}}), ddd);
    assert Arrays.equals(solution.shiftingLetters("hello", new int[]{{0,4,1},{1,3,0}}), iellp);
    assert Arrays.equals(solution.shiftingLetters("hello", new int[]{{0,1,1},{1,2,1},{2,3,1},{3,4,1}}), ignnp);
    assert Arrays.equals(solution.shiftingLetters("abcdefghijklmnopqrstuvwxyz", new int[]{{0,25,1}}), bcdefghijklmnopqrstuvwxyza);
    assert Arrays.equals(solution.shiftingLetters("dztz", new int[]{{0,0,0},{1,1,1}}), catz);
    assert Arrays.equals(solution.shiftingLetters("zyxwvutsrqponmlkjihgfedcba", new int[]{{0,25,0}}), yxwvutsrqponmlkjihgfedcbaz);
    assert Arrays.equals(solution.shiftingLetters("a", new int[]{{0,0,1},{0,0,0}}), a);
